def base(key,title,formula='Ag',kind='procedure',method='Supporting procedure'):
 r=record(PRE+key,'Shah et al. (2001) · '+title,formula,'Ligand-stabilized metal nanocrystals',method,deepcopy(SRC),'Complete supplied main PDF pp. 1–8',kind)
 r['schema_version']='1.3.0';r['collection']='reviewed_literature';r['lineage']['recipe_family']='shah2001-'+formula.lower()+'-sc-co2'
 r['intended_target']['composition']=F(formula if kind=='literature_protocol' else None,note='' if kind=='literature_protocol' else 'Procedure or evidence context, not an independent synthesis target.')
 r['quality'].update(review_status='imported_unreviewed',review_scope='Complete eight-page supplied main paper read and visually inspected. Independent audit, reader integration and publication pending. SI not located or verified.',requested_tasks=['precursor_selection','partial_protocol'] if kind=='literature_protocol' else [],experimental_outcome='reported_product' if kind=='literature_protocol' else 'not_established',missing_fields=['SI not located or verified; absence is not established.','No measured atomic coordinates, refined unit cell, experimental CIF, XRD or SAED supplied.','Unless explicitly named, source figures lack an assigned Table 1 experiment or physical batch identity.'],conflicts=[])
 r['context_links']=[{'label':'Complete supplied main-paper review','url':'../paper-review.html?id=shah2001','relation':'Source text, all figures, table, equations and limitations.'}]
