def route_materials(precursor):
 ms=[C(precursor,'metal_precursor',notes=['Aldrich Chemical Co.; purity not specified.'] if precursor=='agacac' else ['Strem Chemicals, Inc.; purity not specified.']),C('c8-thiol','capping_ligand',notes=['Oakwood Products Inc.; source condensed formula C6F13C2H4SH. Free thiol reagent and surface-bound thiolate are distinct states.']),C('co2','solvent',quantities={'supplier_purity':Q(u='%',minimum=99.99,minimum_exclusive=True,raw_text='>99.99%')},notes=['Matheson Gas Products; used as received. Backside pressure-fluid CO2 is distinct from reactor contents.']),C('hydrogen','reducing_agent',quantities={'supplier_purity':Q(u='%',minimum=99.999,minimum_exclusive=True,raw_text='>99.999%')},notes=['Praxair, Inc.; used as received.']),C('acetone','collection_and_redispersion_solvent',stage='workup',notes=['Omnisolv spectrophotometry grade, EM Science.']),C('heptane','antisolvent',stage='workup')]
 if precursor=='pt-precursor':ms[0]['notes'].append('The article prints cyclopentadiene on pp. 9434 and 9436. Identity is unresolved; do not silently substitute cyclooctadiene, a molecular formula or a connectivity model.')
 return ms
