 add(r,'fill','pressurized_solvent_filling','Seal the cell and introduce carbon dioxide',['charged','co2'],'filled',params=fill,depends=['load'],description=shared+' Numerical fill volume and reactor working volume are supplied only for the typical Ag framework.' if not typical else 'The 14–18 mL CO2 fill and 27 mL cell working volume have different meanings and must not be substituted for one another.',environment='CO2')
