 add(r,'condition','pressurization_and_heating','Set reaction pressure and temperature',['filled'],'conditioned',e+SYN,params=params,depends=['fill'],description='CO2 on the backside of the piston raises pressure; Dionex model 501 computer-controlled syringe pump. Heating tape with Omega CN76000 controller; an inserted thermocouple verifies reaction temperature. The precursor does not decompose at this stage before H2 is added.',environment='Single CO2 reaction phase; piston pressure control')
 pars={'thiol_to_precursor_molar_ratio':Q(ratio,'mol/mol',e=e)} if ratio is not None else {'thiol_mass':Q(u='mg',minimum=162,maximum=324),'hydrogen_mass':Q(6.22,'mg')}
